    fun `RecordDeposit - a new MakeDeposit produces a Deposit`() {
        val beforeDeposit = count("Deposit")
        // given: a 'MakeDeposit' committed entering 'MakeDeposit' — transient: the act is not kept
        givens.makeDeposit()
        assertEquals(beforeDeposit + 1, count("Deposit"), "rule RecordDeposit: one 'Deposit' per firing")
